private static String infer(SNode expression, Map<String, SNode> questions, List<String> diagnostics) {
  if (expression == null) return null;
  String concept = expression.getConcept().getName();
  if ("Literal".equals(concept)) {
    String type = property(expression, "literalType");
    if (type == null || type.isEmpty()) {
      diagnostics.add("[QL_UNKNOWN_TYPE] literal has no type");
      return null;
    }
    return type;
  }
  if ("Reference".equals(concept)) {
    SNode target = expression.getReferenceTarget("target");
    if (target != null) return property(target, "valueType");
    SNode byId = questions.get(property(expression, "targetId"));
    return byId == null ? null : property(byId, "valueType");
  }
  if ("Unary".equals(concept)) {
    String operator = property(expression, "operator");
    String operand = infer(child(expression, "operand"), questions, diagnostics);
    if ("!".equals(operator)) {
      if (!"boolean".equals(operand)) diagnostics.add("[QL_OPERAND_TYPE] unary ! requires boolean, got " + operand);
      return "boolean";
    }
    if ("-".equals(operator)) {
      if (!isNumeric(operand)) diagnostics.add("[QL_OPERAND_TYPE] unary - requires a numeric operand, got " + operand);
      return isNumeric(operand) ? operand : null;
    }
    diagnostics.add("[QL_OPERATOR] unsupported unary operator " + operator);
    return null;
  }
  if ("Binary".equals(concept)) {
    String operator = property(expression, "operator");
    String left = infer(child(expression, "left"), questions, diagnostics);
    String right = infer(child(expression, "right"), questions, diagnostics);
    if ("&&".equals(operator) || "||".equals(operator)) {
      if (!"boolean".equals(left) || !"boolean".equals(right)) diagnostics.add("[QL_OPERAND_TYPE] " + operator + " requires boolean operands, got " + left + " and " + right);
      return "boolean";
    }
    if ("+".equals(operator)) {
      if (isNumeric(left) && isNumeric(right)) return promote(left, right);
      if ("string".equals(left) && "string".equals(right)) return "string";
      diagnostics.add("[QL_OPERAND_TYPE] + requires two numeric operands or two strings, got " + left + " and " + right);
      return null;
    }
    if ("-".equals(operator) || "*".equals(operator) || "/".equals(operator)) {
      if (!isNumeric(left) || !isNumeric(right)) {
        diagnostics.add("[QL_OPERAND_TYPE] " + operator + " requires numeric operands, got " + left + " and " + right);
        return null;
      }
      if ("/".equals(operator) && !"money".equals(left) && !"money".equals(right)) return "decimal";
      return promote(left, right);
    }
    if ("==".equals(operator) || "!=".equals(operator)) {
      if (!(left != null && left.equals(right)) && !(isNumeric(left) && isNumeric(right))) diagnostics.add("[QL_OPERAND_TYPE] " + operator + " requires compatible operands, got " + left + " and " + right);
      return "boolean";
    }
    if (">".equals(operator) || "<".equals(operator) || ">=".equals(operator) || "<=".equals(operator)) {
      boolean compatible = left != null && left.equals(right) && !"boolean".equals(left) || isNumeric(left) && isNumeric(right);
      if (!compatible) diagnostics.add("[QL_OPERAND_TYPE] " + operator + " requires compatible ordered operands, got " + left + " and " + right);
      return "boolean";
    }
    diagnostics.add("[QL_OPERATOR] unsupported binary operator " + operator);
    return null;
  }
  diagnostics.add("[QL_UNKNOWN_TYPE] unsupported expression " + concept);
  return null;
}
